"""Parse duration strings into seconds."""

import re


_PATTERN = re.compile(
    r"\s*(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?\s*"
)
_UNIT_SECONDS = (86400, 3600, 60, 1)


def parse_duration(s):
    """Return the number of seconds represented by a duration string."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _PATTERN.fullmatch(s)
    if match is None or all(part is None for part in match.groups()):
        raise ValueError(f"invalid duration: {s!r}")

    return sum(
        int(amount) * seconds
        for amount, seconds in zip(match.groups(), _UNIT_SECONDS)
        if amount is not None
    )
